def shortest_path(grid, k):
    m, n = len(grid), len(grid[0])
    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]
    queue = deque([(0, 0, k, 0)])
    seen = {(0, 0, k)}
    while queue:
        r, c, remain, steps = queue.popleft()
        if (r, c) == (m - 1, n - 1):
            return steps
        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if 0 <= nr < m and 0 <= nc < n:
                if grid[nr][nc] == 0:
                    state = (nr, nc, remain)
                elif remain > 0:
                    state = (nr, nc, remain - 1)
                else:
                    continue
                if state not in seen:
                    seen.add(state)
                    queue.append(state + (steps + 1,))
    return -1

