def total_n_queens(n):
    def backtrack(row, diagonals, anti, cols):
        if row == n:
            return 1
        solutions = 0
        for col in range(n):
            d, a = row - col, row + col
            if col in cols or d in diagonals or a in anti:
                continue
            cols.add(col); diagonals.add(d); anti.add(a)
            solutions += backtrack(row + 1, diagonals, anti, cols)
        return solutions
    return backtrack(0, set(), set(), set())

